if (head == nullptr) {
    return false;
}

if (head->value == value) {
    ListNode* temp = head;
    head = head->next;
    delete temp;
    return true;
}

ListNode* current = head;
while (current->next != nullptr) {
    if (current->next->value == value) {
        ListNode* temp = current->next;
        current->next = current->next->next;
        delete temp;
        return true;
    }
    current = current->next;
}

return false;

